export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  const eps = 1e-6;
  let st = 'Rising';
  if (t <= eps) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t > T - eps) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const py = 380 - y / 2.2 * 300;
  o.push(sdk.circle('ball.toss', 130, py, 26));
  o.push(...sdk.vector('vec.v', { x: 130, y: py }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 160, y: py }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  o.push(sdk.callout(190, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [], N = 20;
  for (let i = 0; i <= N; i++) { const s = 1.8 * i / N; pts.push({ x: s, y: sdk.clamp(u - g * s, -5.5, 5.5) }); }
  const cur = [], K = 12;
  for (let i = 0; i <= K; i++) { const s = t * i / K; cur.push({ x: s, y: u - g * s }); }
  o.push(sdk.plot('plot.vt', { x: 370, y: 50, w: 260, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: pts }, { label: 'so far', kind: 'line', points: cur }] }));
  o.push(sdk.text('plot.vt.note', 500, 395, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s^2', { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F } };
}
